/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlatrs = require( './../lib/dlatrs.js' );


// FIXTURES //

var NO_TRANS_UPPER_ROW_MAJOR = require( './fixtures/no_trans_upper_row_major.json' );
var NO_TRANS_UPPER_COL_MAJOR = require( './fixtures/no_trans_upper_col_major.json' );
var NO_TRANS_LOWER_ROW_MAJOR = require( './fixtures/no_trans_lower_row_major.json' );
var NO_TRANS_LOWER_COL_MAJOR = require( './fixtures/no_trans_lower_col_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlatrs, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( dlatrs.length, 10, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var CNORM;
	var data;
	var A;
	var X;
	var i;

	data = NO_TRANS_UPPER_COL_MAJOR;

	A = new Float64Array( data.A );
	X = new Float64Array( data.X );
	CNORM = new Float64Array( data.CNORM );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlatrs( value, data.uplo, data.trans, data.diag, data.normin, data.N, A, data.LDA, X, CNORM );
		};
	}
});

